/**
 * OPay gateway adapter — ported from OwnPay-Gateway-Plugin/opay.
 * GENERATED by scripts/port-gateways/generate.py — regenerate, do not hand-edit.
 * Flow: rest.
 * PORT-NOTE: sandbox "simulation" fallback (SIM_/uniqid fake success) stripped — API failure now throws.
 */

import {
  BaseGatewayAdapter,
  type GatewayMetadata,
  type GatewayField,
  type InitiateParams,
  type InitiateResult,
  type VerifyResult,
  type Credentials,
  type GatewayContext,
} from '../base';
import { gwJson } from '../kit/http';
import { hmacHex, timingSafeEqual } from '../../lib/hash';

const SANDBOX_URL = "https://testapi.opaycheckout.com";
const LIVE_URL = "https://api.opaycheckout.com";

const SLUG = "opay";

export class OpayGateway extends BaseGatewayAdapter {
  metadata(): GatewayMetadata {
    return {
      name: "OPay",
      slug: "opay",
      version: '1.0.0',
      description: "OPay Cashier Checkout and Digital Wallet Integration",
      author: 'OwnPay Gateway Plugin Suite (AGPLv3) — EdgePay port',
      type: 'gateway',
      supported_currencies: ["NGN", "EGP"],
      capabilities: ["verification", "webhook"],
    };
  }

  fields(): GatewayField[] {
    return [
      { name: "merchant_id", label: "Merchant ID", type: "text" as const, required: true },
      { name: "public_key", label: "Public Key (Bearer token)", type: "text" as const, required: true },
      { name: "secret_key", label: "Secret Key (Webhook Signature key)", type: "password" as const, required: true },
    ];
  }

  async initiate(params: InitiateParams, credentials: Credentials, _ctx?: GatewayContext): Promise<InitiateResult> {
    const merchantId = String(credentials["merchant_id"] ?? '');
    const publicKey = String(credentials["public_key"] ?? '');
    const mode = String(credentials.mode ?? 'sandbox');
    const amountRaw = (params.amount ?? '');
    const amountStr = ((!isNaN(Number(amountRaw)))) ? (String(amountRaw)) : ("0.00");
    const amountCents = Math.trunc(Number(String(Math.round(Number(amountStr) * 100))));
    const baseUrl = (String(mode) === String("live")) ? (LIVE_URL) : (SANDBOX_URL);
    const metadata = (params.metadata ?? []);
    const country = String((((metadata) as Record<string, unknown>)["country"] ?? "NG") ?? '');
    const payload = { ["country"]: String(country).toUpperCase(), ["reference"]: (params.trx_id ?? ''), ["amount"]: { ["total"]: amountCents, ["currency"]: String((params.currency ?? '')).toUpperCase() }, ["returnUrl"]: (params.redirect_url ?? ''), ["cancelUrl"]: (params.cancel_url ?? ''), ["product"]: { ["name"]: `Payment ${String((params.trx_id ?? ''))}`, ["description"]: "OwnPay Secure Checkout" } };
    const res = await gwJson({
      url: `${String(baseUrl)}/api/v1/international/cashier/create`,
      method: 'POST',
      headers: { ["Content-Type"]: "application/json", ["Authorization"]: `Bearer ${String(publicKey)}`, ["MerchantId"]: `${String(merchantId)}`, ["Accept"]: "application/json" },
      body: JSON.stringify(payload),
      timeoutMs: 15000,
    });
    if (res.status !== 200) throw new Error(`${SLUG}: HTTP ${res.status} ${res.text}`);
    if (res.data === null) throw new Error(`${SLUG}: invalid response`);
    const d = res.data as Record<string, unknown>;
    const cashierUrl = String(((d) as Record<string, unknown>)["cashierUrl"] ?? '');
    return {
          redirect_url: (cashierUrl || undefined) as string | undefined,
          session_id: ((params.trx_id ?? '') || undefined) as string | undefined,
        };
  }

  async verify(callbackData: Record<string, unknown>, _credentials: Credentials, _ctx?: GatewayContext): Promise<VerifyResult> {
    const cb = callbackData as Record<string, unknown>;
    if (String(cb["_op_webhook_verified"] ?? '') !== 'true') {
          return { success: false, gateway_trx_id: '', amount: null, status: 'failed' as const };
        }
    const amountNum = ((!isNaN(Number(cb["amount"])))) ? (cb["amount"]) : ("0.00");
    const amountDecimal = (Number(amountNum) + Number("0")).toFixed(2);
    // PORT-NOTE: upstream verifies via the callback payload only (no
    // server-side API); the unguessable checkout callback token is the
    // authenticity gate for this flow.
    const ok = false;
    return {
          success: ok,
          gateway_trx_id: String(cb["gateway_trx_id"] ?? ''),
          amount: (String(amountDecimal ?? '') || null) as string | null,
          status: (ok ? 'completed' : 'failed') as VerifyResult['status'],
        };
  }

  async verifyWebhook(input: { rawBody: string; headers: Record<string, string>; credentials: Credentials }): Promise<boolean> {
    const credentials = input.credentials;
    const secret = credentials["secret_key"] ?? '';
    if (secret === '') return false; // fail-closed
    const provided = input.headers["X-OPay-Signature"] ?? '';
    if (provided === '') return false;
    const expected = await hmacHex('SHA-512', input.rawBody, secret);
    return timingSafeEqual(expected, provided);
  }
}
